 <section class="admin-card"><div class="admin-section-heading"><div><span class="admin-overline">PAR JOUR</span><h2>Points financiers quotidiens</h2></div></div><div class="admin-table-wrap"><table><thead><tr><th>Date UTC</th><th>Paiements reçus</th><th>Cautions remboursées</th><th>Flux net Paiement Pro</th><th>Entrées de caisse</th><th>Sorties de caisse</th></tr></thead><tbody><?php foreach($report['daily'] as $row): ?><tr><td><?= $escape($row['date']) ?></td><td><?= $money($row['collected']) ?></td><td><?= $money($row['refunded']) ?></td><td><?= $money($row['collected']-$row['refunded']-$row['withdrawn']) ?></td><td><?= $money($row['cashIn']) ?></td><td><?= $money($row['cashOut']) ?></td></tr><?php endforeach; ?><?php if(!$report['daily']): ?><tr><td colspan="6">Aucune opération confirmée sur la période.</td></tr><?php endif; ?></tbody></table></div></section>
